            borderStyle="round"
            padding={1}
            marginBottom={1}
          >
            <Text color="white">
              {runner.agent.name} - {status.status}
            </Text>
            <Box marginLeft={2} flexDirection="column">
              <Text>{status.output}</Text>
            </Box>
          </Box>
        );
      })}
    </Box>
  );
};

