      await initializeGlobalAgentRegistry(mockProjectRoot);
      expect(getGlobalAgentRegistry().size()).toBe(1);

      disposeGlobalAgentRegistry();
      expect(() => getGlobalAgentRegistry()).toThrow(
        'Global agent registry not initialized',
      );
    });
  });
});

