  private readonly ideMode: boolean;
  private readonly enableOpenAILogging: boolean;
  private readonly sampling_params?: {
    top_p?: number;
    top_k?: number;
    repetition_penalty?: number;
    presence_penalty?: number;
    frequency_penalty?: number;
