const createFakeCompletedToolCall = (
  name: string,
  success: boolean,
  duration = 100,
  outcome?: ToolConfirmationOutcome,
  error?: Error,
): CompletedToolCall => {
  const request = {
    callId: `call_${name}_${Date.now()}`,
    name,
    args: { foo: 'bar' },
    isClientInitiated: false,
    prompt_id: 'prompt-id-1',
  };

  if (success) {
    return {
      status: 'success',
      request,
      tool: { name } as Tool, // Mock tool
      response: {
        callId: request.callId,
        responseParts: {
          functionResponse: {
            id: request.callId,
            name,
            response: { output: 'Success!' },
          },
        },
        error: undefined,
        resultDisplay: 'Success!',
      },
      durationMs: duration,
      outcome,
    } as SuccessfulToolCall;
  } else {
    return {
      status: 'error',
      request,
      response: {
        callId: request.callId,
        responseParts: {
          functionResponse: {
            id: request.callId,
            name,
            response: { error: 'Tool failed' },
          },
        },
        error: error || new Error('Tool failed'),
        resultDisplay: 'Failure!',
      },
      durationMs: duration,
      outcome,
    } as ErroredToolCall;
  }
};

describe('UiTelemetryService', () => {
