        expect.stringContaining(
          path.join(tempDir, 'gemini-cli-tool-modify-diffs'),
        ),
        proposedContent,
        'utf8',
      );

      expect(mockOpenDiff).toHaveBeenCalledWith(
        expect.stringContaining('-old-'),
