          '  Tools:',
          agent.tools?.map((t) => t.name || t).join(', '),
        );
        console.log('  Model:', agent.model);
        console.log('  Provider:', agent.provider);
        console.log('  Has System Prompt:', !!agent.systemPrompt);
        if (agent.systemPrompt) {
          console.log(
